// Which source files / packages the bytes of a built JavaScript chunk come from, using its sourcemap.
//   cd frontend && npx vite build --sourcemap --outDir ../.perf-sourcemap-build --emptyOutDir   (a throwaway build, not the real dist)
//   node tools/perf/bundle-attribution.cjs .perf-sourcemap-build/assets [chunk-name-prefix] [top n]
// The generated bytes of each mapped segment are charged to the source it maps to: approximate (minified bytes, not original bytes) but
// it ranks packages correctly, which is what is needed to see where a bundle's weight is.
const fs = require('fs')
const path = require('path')

const dir = path.resolve(process.argv[2])
const prefix = process.argv[3] || 'index-'
const top = Number(process.argv[4] || 18)
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const val = new Int8Array(128).fill(-1)
for (let i = 0; i < 64; i++) val[B64.charCodeAt(i)] = i

function attribute(file) {
  const code = fs.readFileSync(file, 'utf8')
  const map = JSON.parse(fs.readFileSync(file + '.map', 'utf8'))
  const lines = code.split('\n')
  const bySource = new Map()
  let srcIdx = 0
  const mappings = map.mappings.split(';')
  for (let ln = 0; ln < mappings.length; ln++) {
    const segs = mappings[ln].split(',')
    let col = 0
    const starts = []
    for (const seg of segs) {
      if (!seg) continue
      const nums = []
      let shift = 0, acc = 0
      for (let i = 0; i < seg.length; i++) {
        const d = val[seg.charCodeAt(i)]
        acc += (d & 31) << shift
        if (d & 32) shift += 5
        else { nums.push(acc & 1 ? -(acc >> 1) : acc >> 1); acc = 0; shift = 0 }
      }
      col += nums[0]
      if (nums.length > 1) { srcIdx += nums[1]; starts.push([col, srcIdx]) } else starts.push([col, -1])
      // (line/column deltas of the source are tracked implicitly: only the source index is needed here)
      if (nums.length > 2) { /* source line */ }
    }
    const text = lines[ln] || ''
    for (let s = 0; s < starts.length; s++) {
      const end = s + 1 < starts.length ? starts[s + 1][0] : text.length
      const name = starts[s][1] < 0 ? '(unmapped)' : map.sources[starts[s][1]]
      bySource.set(name, (bySource.get(name) || 0) + Math.max(0, end - starts[s][0]))
    }
  }
  return bySource
}

for (const f of fs.readdirSync(dir).filter((n) => n.startsWith(prefix) && n.endsWith('.js'))) {
  const bySource = attribute(path.join(dir, f))
  const groups = new Map()
  for (const [src, bytes] of bySource) {
    const m = /node_modules\/((?:@[^/]+\/)?[^/]+)/.exec(src.replace(/\\/g, '/'))
    const key = m ? m[1] : src.replace(/\\/g, '/').replace(/^(\.\.\/)+/, '').replace(/^src\//, 'app/').split('/').slice(0, 3).join('/')
    groups.set(key, (groups.get(key) || 0) + bytes)
  }
  const total = [...groups.values()].reduce((a, b) => a + b, 0)
  console.log(`\n${f}   ${(total / 1024).toFixed(0)} KB mapped`)
  for (const [k, v] of [...groups].sort((a, b) => b[1] - a[1]).slice(0, top)) console.log(`  ${(v / 1024).toFixed(1).padStart(7)} KB  ${k}`)
}
